/**
 * Fixtures of the `large-pull-request` rehearsal scenario (design §16): a small synthetic pull request that large
 * mode partitions into three areas when the task's limits are tiny (`LARGE_LIMITS`), plus a generated file and a
 * file GitHub gave no patch for. Under the profile's own limits the same pull request is an ordinary small one.
 */

/** The limits a task sets to make this pull request large: three files over the limit, areas of at most 500 bytes of patch. */
export const LARGE_LIMITS = { maxFiles: 2, areaMaxBytes: 500, areaMinBytes: 1 } as const;

const trivialFuncs = (pkg: string, prefix: string, count: number): string =>
  [`package ${pkg}`, "", ...Array.from({ length: count }, (_, i) => [`// ${prefix}${i + 1} adds ${i + 1}.`, `func ${prefix}${i + 1}(x int) int {`, `\treturn x + ${i + 1}`, "}", ""].join("\n"))].join("\n");

/** Six exported functions: the questions about them come in two batches. */
export const ALPHA_GO = trivialFuncs("alpha", "Alpha", 6);

export const BETA_GO = `package beta

import "example.com/lib/pkg/alpha"

// twice applies Alpha1 twice.
func twice(x int) int {
	return alpha.Alpha1(alpha.Alpha1(x))
}

// Beta applies Alpha1 twice.
func Beta(x int) int {
	return twice(x)
}
`;

export const GUIDE_MD = "# Guide\n\nAlpha and Beta add numbers.\n";

export const GENERATED_GO = "// Code generated by protoc-gen-go. DO NOT EDIT.\n\npackage gen\n\ntype Types struct{}\n";

/** The path of the file GitHub gave no patch for (a binary file). */
export const OMITTED_PATH = "assets/logo.png";

/** The head's files the stubbed checkout does not write and the static tools and the symbol extraction read. */
export const LARGE_HEAD_FILES: Readonly<Record<string, string>> = {
  "pkg/alpha/alpha.go": ALPHA_GO,
  "pkg/beta/beta.go": BETA_GO,
};

/** What `gometrics` prints for a file of trivial functions: complexity 1, nesting 0, each from its `func` line to the closing brace at column 0. */
export function trivialDoc(path: string, pkg: string, text: string): { schema: string; tool: string; records: unknown[]; files: unknown[]; skipped: unknown[] } {
  const lines = text.split("\n");
  const functions: Array<[string, number, number]> = [];
  lines.forEach((l, i) => {
    const m = /^func (\w+)\(/.exec(l);
    if (m === null) return;
    const end = lines.findIndex((x, j) => j > i && x === "}");
    functions.push([`${pkg}.${m[1]}`, i + 1, end + 1]);
  });
  return {
    schema: "graphloom-metrics-v1",
    tool: "gometrics",
    records: functions.map(([name, start, end]) => ({ path, function: name, startLine: start, endLine: end, change: "added", test: false, complexity: 1, decisions: [], nesting: 0, nestingPath: [] })),
    files: [{ path, language: "go", test: false, functions }],
    skipped: [],
  };
}

/** The static tool's output for the whole pull request: both files' records. */
export function largeDoc(): { schema: string; tool: string; records: unknown[]; files: unknown[]; skipped: unknown[] } {
  const a = trivialDoc("pkg/alpha/alpha.go", "alpha", ALPHA_GO);
  const b = trivialDoc("pkg/beta/beta.go", "beta", BETA_GO);
  return { schema: a.schema, tool: a.tool, records: [...a.records, ...b.records], files: [...a.files, ...b.files], skipped: [] };
}
